/**
 * CSV writer. Quoting rules are defined by the README: quote a field iff it
 * contains comma, double quote, LF or CR; double quotes inside quoted fields
 * are escaped by doubling.
 */
export function toCsv(columns, rows) {
  function renderField(value) {
    const text = String(value ?? '')
    if (/[",\n\r]/.test(text)) {
      return `"${text}"`
    }
    return text
  }

  const lines = [columns.map((column) => renderField(column.name)).join(',')]
  for (const row of rows) {
    lines.push(columns.map((column) => renderField(row[column.key])).join(','))
  }
  return lines.join('\n')
}

/** ISO calendar date (UTC, YYYY-MM-DD) from an epoch-millisecond timestamp. */
export function formatIsoDate(epochMs) {
  const date = new Date(epochMs)
  const year = String(date.getUTCFullYear()).padStart(4, '0')
  const month = String(date.getUTCMonth() + 1).padStart(2, '0')
  const day = String(date.getUTCDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

import { formatIsoDate } from './dates.js'

/** Format integer cents as a display amount, e.g. 1234567 -> "12,345.67". */
export function formatAmount(cents) {
  const negative = cents < 0
  const abs = Math.abs(cents)
  const whole = Math.trunc(abs / 100)
  const fraction = String(abs % 100).padStart(2, '0')
  const grouped = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return `${negative ? '-' : ''}${grouped}.${fraction}`
}

/** Shape a raw order record into a CSV row of strings. */
export function shapeOrderRow(order) {
  return {
    sku: order.sku,
    title: order.title,
    amount: formatAmount(order.amountCents),
    date: formatIsoDate(order.placedAtMs),
  }
}

